// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 timeJump) public {
        vm.assume(amount == 10 ether);
        vm.assume(timeJump > 0 && timeJump <= 100000);

        // Record pre-state
        uint256 prevPastBlockTime = c.pastBlockTime();

        // Warp to a time after the stored pastBlockTime
        vm.warp(block.timestamp + timeJump);

        // Call fallback with exactly 10 ether
        (bool success,) = address(c).call{value: amount}("");

        // Only check if call succeeded
        if (success) {
            uint256 expectedPast = block.timestamp + 1;
            assertTrue(c.pastBlockTime() == expectedPast, "pastBlockTime should be block.timestamp + 1");
        }
    }
}

